import qrcode from 'qrcode-generator';
import { eyePath, modulePath, roundRect, type DotShape, type EyeShape } from './geometry';

export type ErrorCorrection = 'L' | 'M' | 'Q' | 'H';

// The library's default encoder is Latin-1 only; encode as UTF-8 so emoji,
// accents and non-Latin scripts survive the round trip.
const utf8 = new TextEncoder();
qrcode.stringToBytes = (s: string) => Array.from(utf8.encode(s));

export interface LogoInfo {
  /** PNG data URL (kept self-contained so SVG exports have no external refs). */
  src: string;
  width: number;
  height: number;
}

export interface QrOptions {
  data: string;
  ec: ErrorCorrection;
  /** Quiet zone, in modules. */
  margin: number;
  dot: DotShape;
  eye: EyeShape;
  fg: string;
  eyeColor: string;
  /** `null` = transparent background. */
  bg: string | null;
  logo: LogoInfo | null;
}

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface QrRender {
  kind: 'ok';
  svg: string;
  /** Module path for data dots, in module units. */
  dotsPath: string;
  /** Evenodd path for the three finder patterns, in module units. */
  eyesPath: string;
  /** Logo placement in module units, if any. */
  logoRect: Rect | null;
  /** Total side length including margin, in module units. */
  total: number;
  version: number;
  modules: number;
  bytes: number;
  options: QrOptions;
}

export type QrResult = { kind: 'empty' } | { kind: 'error'; message: string } | QrRender;

const r3 = (n: number) => Math.round(n * 1000) / 1000;
const escAttr = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);

export function renderQr(opts: QrOptions): QrResult {
  if (!opts.data) return { kind: 'empty' };

  const qr = qrcode(0, opts.ec);
  try {
    qr.addData(opts.data, 'Byte');
    qr.make();
  } catch {
    return {
      kind: 'error',
      message: "That's too much content for one QR code. Try shortening it" + (opts.ec !== 'L' ? ' or lowering error correction.' : '.'),
    };
  }

  const n = qr.getModuleCount();
  const m = opts.margin;
  const total = n + 2 * m;

  const inEye = (r: number, c: number) => (r < 7 && c < 7) || (r < 7 && c >= n - 7) || (r >= n - 7 && c < 7);

  // Clear a square in the middle for the logo (~24% of the width, odd so it's centred).
  let hole: { x: number; y: number; s: number } | null = null;
  let logoRect: Rect | null = null;
  if (opts.logo) {
    const s = Math.round(n * 0.24) | 1;
    const a = (n - s) / 2;
    hole = { x: a, y: a, s };
    const ratio = opts.logo.width / opts.logo.height;
    const w = ratio > 1 ? s : s * ratio;
    const h = ratio > 1 ? s / ratio : s;
    logoRect = { x: a + (s - w) / 2 + 0.6 + m, y: a + (s - h) / 2 + 0.6 + m, w: w - 1.2, h: h - 1.2 };
  }
  const inHole = (r: number, c: number) =>
    hole !== null && c >= hole.x - 0.5 && c < hole.x + hole.s + 0.5 && r >= hole.y - 0.5 && r < hole.y + hole.s + 0.5;
  const isData = (r: number, c: number) => qr.isDark(r, c) && !inEye(r, c) && !inHole(r, c);

  let dots = '';
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      if (!isData(r, c)) continue;
      if (opts.dot === 'bars') {
        if (r > 0 && isData(r - 1, c)) continue; // already covered by the run above
        let len = 1;
        while (r + len < n && isData(r + len, c)) len++;
        dots += roundRect(c + m + 0.15, r + m + 0.04, 0.7, len - 0.08, 0.35);
      } else {
        dots += modulePath(opts.dot, c + m, r + m, 1);
      }
    }
  }

  const eyes = eyePath(opts.eye, m, m, 7) + eyePath(opts.eye, m + n - 7, m, 7) + eyePath(opts.eye, m, m + n - 7, 7);

  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${total} ${total}" shape-rendering="geometricPrecision">` +
    (opts.bg ? `<rect width="${total}" height="${total}" fill="${escAttr(opts.bg)}"/>` : '') +
    `<path fill="${escAttr(opts.fg)}" d="${dots}"/>` +
    `<path fill="${escAttr(opts.eyeColor)}" fill-rule="evenodd" d="${eyes}"/>` +
    (logoRect && opts.logo
      ? `<image href="${escAttr(opts.logo.src)}" x="${r3(logoRect.x)}" y="${r3(logoRect.y)}" width="${r3(logoRect.w)}" height="${r3(logoRect.h)}" preserveAspectRatio="xMidYMid meet"/>`
      : '') +
    '</svg>';

  return {
    kind: 'ok',
    svg,
    dotsPath: dots,
    eyesPath: eyes,
    logoRect,
    total,
    version: (n - 17) / 4,
    modules: n,
    bytes: utf8.encode(opts.data).length,
    options: opts,
  };
}

/** Rasterise a render to a square canvas of `px` pixels. */
export function drawToCanvas(res: QrRender, px: number, logoImg: CanvasImageSource | null): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = px;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas 2D is not available');
  const k = px / res.total;
  ctx.scale(k, k);
  const o = res.options;
  if (o.bg) {
    ctx.fillStyle = o.bg;
    ctx.fillRect(0, 0, res.total, res.total);
  }
  ctx.fillStyle = o.fg;
  if (res.dotsPath) ctx.fill(new Path2D(res.dotsPath));
  ctx.fillStyle = o.eyeColor;
  ctx.fill(new Path2D(res.eyesPath), 'evenodd');
  if (res.logoRect && logoImg) {
    const L = res.logoRect;
    ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(logoImg, L.x, L.y, L.w, L.h);
  }
  return canvas;
}
