import './styles.css';
import { contrastRatio, luminance, PALETTES } from './color';
import { buildPayload, CONTENT_TYPES, type ContentType, type ContentTypeId } from './content-types';
import { DOT_SHAPES, EYE_SHAPES, eyePath, modulePath } from './geometry';
import { drawToCanvas, renderQr, type ErrorCorrection, type LogoInfo, type QrRender } from './qr';
import { EXPORT_SIZES, loadState, saveState } from './state';

// ---------- DOM helpers ----------
function $<T extends HTMLElement = HTMLElement>(id: string): T {
  const el = document.getElementById(id);
  if (!el) throw new Error(`Missing #${id}`);
  return el as T;
}
const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
const INK = '#1B1A17';
const LOGO_PLACEHOLDER =
  '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#5B574E" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="9" cy="9" r="2"/><path d="M21 15l-5-5L5 21"/></svg>';
const LOGO_HINT = 'Drop an image here, or choose one. Error correction switches to High so it still scans.';
const EMPTY_HINT = 'Type something on the left and your code appears here.';
const EC_HINT: Record<ErrorCorrection, string> = { L: 'recovers ~7%', M: 'recovers ~15%', Q: 'recovers ~25%', H: 'recovers ~30%' };

// ---------- State ----------
const state = loadState();
let logo: (LogoInfo & { img: HTMLImageElement | null }) | null = null;
let current: QrRender | null = null;

const effectiveEc = (): ErrorCorrection => (logo ? 'H' : state.ec);

function toast(msg: string): void {
  const t = $('toast') as HTMLElement & { _h?: number };
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(t._h);
  t._h = window.setTimeout(() => t.classList.remove('show'), 2200);
}

// ---------- Content tabs & fields ----------
const tabs = $('tabs');
const form = $<HTMLFormElement>('fields');
form.addEventListener('submit', (e) => e.preventDefault());

for (const [id, def] of Object.entries(CONTENT_TYPES) as [ContentTypeId, ContentType][]) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'tab';
  b.setAttribute('role', 'tab');
  b.dataset.k = id;
  b.innerHTML =
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
    def.icon +
    '</svg>' +
    esc(def.label);
  b.addEventListener('click', () => {
    state.type = id;
    renderFields();
    update();
  });
  tabs.appendChild(b);
}

function renderFields(): void {
  for (const b of tabs.children) (b as HTMLElement).setAttribute('aria-selected', String((b as HTMLElement).dataset.k === state.type));
  const def: ContentType = CONTENT_TYPES[state.type];
  const vals = state.values[state.type];
  form.innerHTML = '';
  let pair: HTMLDivElement | null = null;

  for (const f of def.fields) {
    const label = document.createElement('label');
    if (f.kind === 'check') {
      label.className = 'check';
      const inp = document.createElement('input');
      inp.type = 'checkbox';
      inp.checked = vals[f.key] === true;
      inp.addEventListener('change', () => {
        vals[f.key] = inp.checked;
        update();
      });
      label.append(inp, ' ' + f.label);
    } else {
      label.className = 'f';
      let ctl: HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement;
      if (f.kind === 'textarea') ctl = document.createElement('textarea');
      else if (f.kind === 'select') {
        ctl = document.createElement('select');
        for (const [v, l] of f.options ?? []) ctl.add(new Option(l, v));
      } else {
        ctl = document.createElement('input');
        ctl.type = f.kind;
      }
      if (f.placeholder && !(ctl instanceof HTMLSelectElement)) ctl.placeholder = f.placeholder;
      ctl.value = String(vals[f.key] ?? '');
      ctl.addEventListener(f.kind === 'select' ? 'change' : 'input', () => {
        vals[f.key] = ctl.value;
        update();
      });
      label.append(f.label, ctl);
    }

    if (f.half) {
      if (!pair) {
        pair = document.createElement('div');
        pair.className = 'row2';
        form.appendChild(pair);
      }
      pair.appendChild(label);
      if (pair.children.length === 2) pair = null;
    } else {
      pair = null;
      form.appendChild(label);
    }
  }
}

// ---------- Colours ----------
const presetsEl = $('presets');
for (const p of PALETTES) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'sw';
  b.title = p.id;
  b.setAttribute('aria-label', `${p.id} palette`);
  b.dataset.id = p.id;
  b.innerHTML =
    `<i style="background:${p.bg}"></i>` +
    `<i style="background:${p.fg};clip-path:polygon(0 0,100% 0,0 100%)"></i>` +
    `<i style="background:${p.eye};inset:auto 6px 6px auto;width:12px;height:12px;border-radius:4px"></i>`;
  b.addEventListener('click', () => {
    Object.assign(state, { fg: p.fg, eye: p.eye, bg: p.bg, preset: p.id });
    syncColors();
    update();
  });
  presetsEl.appendChild(b);
}

const colorInputs = [
  ['cFg', 'fg'],
  ['cEye', 'eye'],
  ['cBg', 'bg'],
] as const;

function syncColors(): void {
  for (const [id, key] of colorInputs) {
    $<HTMLInputElement>(id).value = state[key];
    $(id + 'T').textContent = state[key].toUpperCase();
  }
  for (const b of presetsEl.children) (b as HTMLElement).setAttribute('aria-pressed', String((b as HTMLElement).dataset.id === state.preset));
}
for (const [id, key] of colorInputs) {
  $<HTMLInputElement>(id).addEventListener('input', (e) => {
    state[key] = (e.target as HTMLInputElement).value;
    state.preset = null;
    syncColors();
    update();
  });
}
$<HTMLInputElement>('transparent').addEventListener('change', (e) => {
  state.transparent = (e.target as HTMLInputElement).checked;
  update();
});

// ---------- Shape pickers ----------
function choiceGroup<K extends 'dot' | 'eyeShape'>(el: HTMLElement, items: [string, string, string][], key: K): void {
  const sync = () => {
    for (const b of el.children) (b as HTMLElement).setAttribute('aria-pressed', String((b as HTMLElement).dataset.v === state[key]));
  };
  for (const [v, label, svg] of items) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'choice';
    b.dataset.v = v;
    b.innerHTML = `<svg viewBox="0 0 30 30" aria-hidden="true">${svg}</svg>${esc(label)}`;
    b.addEventListener('click', () => {
      (state[key] as string) = v;
      sync();
      update();
    });
    el.appendChild(b);
  }
  sync();
}

const dotIcon = (shape: (typeof DOT_SHAPES)[number][0]) =>
  [[0, 0], [1, 0], [0, 1], [2, 1], [1, 2], [2, 2]]
    .map(([x, y]) => `<path fill="${INK}" d="${modulePath(shape, 3 + x * 8, 3 + y * 8, 8)}"/>`)
    .join('');
const eyeIcon = (shape: (typeof EYE_SHAPES)[number][0]) => `<path fill-rule="evenodd" fill="${INK}" d="${eyePath(shape, 2, 2, 26)}"/>`;

choiceGroup($('dotShapes'), DOT_SHAPES.map(([v, l]) => [v, l, dotIcon(v)]), 'dot');
choiceGroup($('eyeShapes'), EYE_SHAPES.map(([v, l]) => [v, l, eyeIcon(v)]), 'eyeShape');

// ---------- Error correction, margin, export size ----------
const ecSeg = $('ecSeg');
for (const l of ['L', 'M', 'Q', 'H'] as const) {
  const b = document.createElement('button');
  b.type = 'button';
  b.textContent = l;
  b.dataset.v = l;
  b.addEventListener('click', () => {
    state.ec = l;
    syncEc();
    update();
  });
  ecSeg.appendChild(b);
}
function syncEc(): void {
  const eff = effectiveEc();
  for (const el of ecSeg.children) {
    const b = el as HTMLButtonElement;
    b.setAttribute('aria-pressed', String(b.dataset.v === eff));
    b.disabled = !!logo && b.dataset.v !== 'H';
    b.style.opacity = b.disabled ? '.4' : '1';
  }
  $('ecHint').textContent = EC_HINT[eff] + (logo ? ' · logo' : '');
}

const marginEl = $<HTMLInputElement>('margin');
marginEl.addEventListener('input', () => {
  state.margin = Number(marginEl.value);
  $('marginV').textContent = String(state.margin);
  update();
});

const sizeSeg = $('sizeSeg');
for (const s of EXPORT_SIZES) {
  const b = document.createElement('button');
  b.type = 'button';
  b.textContent = String(s);
  b.dataset.v = String(s);
  b.addEventListener('click', () => {
    state.size = s;
    syncSize();
    saveState(state);
  });
  sizeSeg.appendChild(b);
}
function syncSize(): void {
  for (const b of sizeSeg.children) (b as HTMLElement).setAttribute('aria-pressed', String(Number((b as HTMLElement).dataset.v) === state.size));
}

// ---------- Logo ----------
const logoFile = $<HTMLInputElement>('logoFile');

function loadLogo(file: File | undefined): void {
  if (!file || !file.type.startsWith('image/')) {
    toast("That file isn't an image");
    return;
  }
  const url = URL.createObjectURL(file);
  const img = new Image();
  img.onload = () => {
    URL.revokeObjectURL(url);
    // Normalise to a ≤512px PNG data URL so SVG exports stay self-contained.
    const max = 512;
    const scale = Math.min(1, max / Math.max(img.naturalWidth, img.naturalHeight));
    const c = document.createElement('canvas');
    c.width = Math.max(1, Math.round(img.naturalWidth * scale));
    c.height = Math.max(1, Math.round(img.naturalHeight * scale));
    c.getContext('2d')?.drawImage(img, 0, 0, c.width, c.height);
    const src = c.toDataURL('image/png');
    logo = { src, width: c.width, height: c.height, img: null };
    const ready = new Image();
    ready.onload = () => {
      if (logo?.src === src) {
        logo.img = ready;
        update();
      }
    };
    ready.src = src;
    $('logoThumb').innerHTML = `<img alt="" src="${src}">`;
    $('logoTxt').textContent = file.name;
    $('logoClear').hidden = false;
    syncEc();
    update();
  };
  img.onerror = () => {
    URL.revokeObjectURL(url);
    toast("Couldn't read that image");
  };
  img.src = url;
}

$('logoPick').addEventListener('click', () => logoFile.click());
logoFile.addEventListener('change', () => loadLogo(logoFile.files?.[0]));
$('logoClear').addEventListener('click', () => {
  logo = null;
  logoFile.value = '';
  $('logoThumb').innerHTML = LOGO_PLACEHOLDER;
  $('logoTxt').textContent = LOGO_HINT;
  $('logoClear').hidden = true;
  syncEc();
  update();
});
const drop = $('logoDrop');
for (const ev of ['dragover', 'dragenter']) {
  drop.addEventListener(ev, (e) => {
    e.preventDefault();
    drop.classList.add('drag');
  });
}
for (const ev of ['dragleave', 'drop']) {
  drop.addEventListener(ev, (e) => {
    e.preventDefault();
    drop.classList.remove('drag');
  });
}
drop.addEventListener('drop', (e) => loadLogo((e as DragEvent).dataTransfer?.files[0]));

// ---------- Render ----------
let raf = 0;
function update(): void {
  cancelAnimationFrame(raf);
  raf = requestAnimationFrame(render);
  saveState(state);
}

function render(): void {
  $('kind').textContent = CONTENT_TYPES[state.type].label;
  const res = renderQr({
    data: buildPayload(state.type, state.values[state.type]),
    ec: effectiveEc(),
    margin: state.margin,
    dot: state.dot,
    eye: state.eyeShape,
    fg: state.fg,
    eyeColor: state.eye,
    bg: state.transparent ? null : state.bg,
    logo,
  });
  const stage = $('stage');
  const warn: string[] = [];

  if (res.kind !== 'ok') {
    current = null;
    stage.innerHTML = `<div class="empty">${esc(res.kind === 'error' ? res.message : EMPTY_HINT)}</div>`;
    $('metaV').textContent = '—';
    $('metaC').textContent = '—';
    $('payloadShow').textContent = '';
    $('payloadShow').title = '';
  } else {
    current = res;
    stage.innerHTML = res.svg;
    stage.firstElementChild?.classList.add('pop');
    stage.firstElementChild?.setAttribute('role', 'img');
    stage.firstElementChild?.setAttribute('aria-label', `QR code for ${CONTENT_TYPES[state.type].label}`);
    $('metaV').textContent = `v${res.version} · ${res.modules}×${res.modules} · EC ${res.options.ec}`;
    $('metaC').textContent = `${res.bytes} bytes`;
    $('payloadShow').textContent = res.options.data.replace(/\n/g, ' ⏎ ');
    $('payloadShow').title = res.options.data;

    const ref = state.transparent ? '#FFFFFF' : state.bg;
    if (Math.min(contrastRatio(state.fg, ref), contrastRatio(state.eye, ref)) < 3)
      warn.push('Low contrast between colours and background — some phones may struggle to scan it.');
    else if (!state.transparent && luminance(state.fg) > luminance(state.bg))
      warn.push("Light-on-dark codes look great but a few older scanners can't read inverted QR codes.");
    if (state.margin < 2) warn.push('A small margin can make scanning unreliable when the code sits next to other artwork.');
    if (state.transparent) warn.push('Transparent: place it on a light, plain background for best scanning.');
  }

  $('warn').classList.toggle('show', warn.length > 0);
  $('warnTxt').textContent = warn.join(' ');
  for (const id of ['dlPng', 'dlSvg', 'copyImg']) {
    const b = $<HTMLButtonElement>(id);
    b.disabled = !current;
    b.style.opacity = current ? '1' : '.45';
  }
}

// ---------- Export ----------
const filename = (ext: string) => `quirk-${state.type}-qr.${ext}`;

function download(name: string, blob: Blob): void {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
  toast('Downloading ' + name);
}

function pngBlob(res: QrRender): Promise<Blob> {
  return new Promise((resolve, reject) =>
    drawToCanvas(res, state.size, logo?.img ?? null).toBlob((b) => (b ? resolve(b) : reject(new Error('PNG encode failed'))), 'image/png'),
  );
}

const logoPending = () => !!logo && !logo.img;

$('dlPng').addEventListener('click', async () => {
  if (!current) return;
  if (logoPending()) return toast('Logo still loading…');
  try {
    download(filename('png'), await pngBlob(current));
  } catch {
    toast("Couldn't create the PNG");
  }
});
$('dlSvg').addEventListener('click', () => {
  if (current) download(filename('svg'), new Blob([current.svg], { type: 'image/svg+xml' }));
});
$('copyImg').addEventListener('click', async () => {
  if (!current) return;
  if (logoPending()) return toast('Logo still loading…');
  const res = current;
  try {
    // Pass a promise so Safari keeps the user-activation context.
    await navigator.clipboard.write([new ClipboardItem({ 'image/png': pngBlob(res) })]);
    toast('Image copied — paste it anywhere');
  } catch {
    try {
      await navigator.clipboard.writeText(res.svg);
      toast('Copied as SVG code');
    } catch {
      toast("Clipboard isn't available here");
    }
  }
});

// ---------- Init ----------
$<HTMLInputElement>('transparent').checked = state.transparent;
marginEl.value = String(state.margin);
$('marginV').textContent = String(state.margin);
syncColors();
syncEc();
syncSize();
renderFields();
render();
