/**
 * SVG path builders. The same path strings feed both the SVG export and the
 * canvas renderer (via Path2D), so the PNG and SVG always match.
 */

export type DotShape = 'square' | 'soft' | 'dots' | 'diamond' | 'bars';
export type EyeShape = 'square' | 'rounded' | 'circle' | 'leaf';

export const DOT_SHAPES: [DotShape, string][] = [
  ['square', 'Square'],
  ['soft', 'Soft'],
  ['dots', 'Dots'],
  ['diamond', 'Gem'],
  ['bars', 'Bars'],
];

export const EYE_SHAPES: [EyeShape, string][] = [
  ['square', 'Square'],
  ['rounded', 'Rounded'],
  ['circle', 'Circle'],
  ['leaf', 'Leaf'],
];

/** Round to 3 decimals to keep path strings compact. */
const f = (n: number): number => Math.round(n * 1000) / 1000;

/** Rounded rectangle. */
export function roundRect(x: number, y: number, w: number, h: number, r: number): string {
  r = Math.min(r, w / 2, h / 2);
  if (r <= 0) return `M${f(x)} ${f(y)}h${f(w)}v${f(h)}h${f(-w)}Z`;
  const arc = (ex: number, ey: number) => `A${f(r)} ${f(r)} 0 0 1 ${f(ex)} ${f(ey)}`;
  return (
    `M${f(x + r)} ${f(y)}H${f(x + w - r)}${arc(x + w, y + r)}` +
    `V${f(y + h - r)}${arc(x + w - r, y + h)}` +
    `H${f(x + r)}${arc(x, y + h - r)}` +
    `V${f(y + r)}${arc(x + r, y)}Z`
  );
}

export function circle(cx: number, cy: number, r: number): string {
  return `M${f(cx - r)} ${f(cy)}a${f(r)} ${f(r)} 0 1 0 ${f(2 * r)} 0a${f(r)} ${f(r)} 0 1 0 ${f(-2 * r)} 0Z`;
}

/** Square with only the top-left and bottom-right corners rounded. */
export function leaf(x: number, y: number, s: number, r: number): string {
  return (
    `M${f(x + r)} ${f(y)}H${f(x + s)}V${f(y + s - r)}` +
    `A${f(r)} ${f(r)} 0 0 1 ${f(x + s - r)} ${f(y + s)}H${f(x)}V${f(y + r)}` +
    `A${f(r)} ${f(r)} 0 0 1 ${f(x + r)} ${f(y)}Z`
  );
}

/** A single data module of size `s` at (x, y). `bars` is drawn per-run elsewhere. */
export function modulePath(shape: DotShape, x: number, y: number, s: number): string {
  switch (shape) {
    case 'square':
      return `M${f(x)} ${f(y)}h${f(s)}v${f(s)}h${f(-s)}Z`;
    case 'soft':
      return roundRect(x + s * 0.04, y + s * 0.04, s * 0.92, s * 0.92, s * 0.32);
    case 'dots':
      return circle(x + s / 2, y + s / 2, s * 0.43);
    case 'diamond': {
      const c = s / 2;
      const k = s * 0.54;
      return `M${f(x + c)} ${f(y + c - k)}L${f(x + c + k)} ${f(y + c)}L${f(x + c)} ${f(y + c + k)}L${f(x + c - k)} ${f(y + c)}Z`;
    }
    case 'bars':
      return roundRect(x + s * 0.15, y, s * 0.7, s, s * 0.35);
  }
}

/**
 * A finder pattern ("eye") of side `s` (= 7 modules): outer ring plus 3×3 pupil.
 * Must be filled with `fill-rule="evenodd"`.
 */
export function eyePath(shape: EyeShape, x: number, y: number, s: number): string {
  const u = s / 7;
  switch (shape) {
    case 'square':
      return roundRect(x, y, s, s, 0) + roundRect(x + u, y + u, s - 2 * u, s - 2 * u, 0) + roundRect(x + 2 * u, y + 2 * u, 3 * u, 3 * u, 0);
    case 'rounded':
      return (
        roundRect(x, y, s, s, u * 2.2) +
        roundRect(x + u, y + u, s - 2 * u, s - 2 * u, u * 1.4) +
        roundRect(x + 2 * u, y + 2 * u, 3 * u, 3 * u, u * 0.9)
      );
    case 'circle':
      return circle(x + s / 2, y + s / 2, s / 2) + circle(x + s / 2, y + s / 2, s / 2 - u) + circle(x + s / 2, y + s / 2, 1.5 * u);
    case 'leaf':
      return leaf(x, y, s, u * 3) + leaf(x + u, y + u, s - 2 * u, u * 2) + leaf(x + 2 * u, y + 2 * u, 3 * u, u * 1.3);
  }
}
