/**
 * Content types: each describes the form fields it needs and how to turn
 * those field values into the string payload encoded in the QR code.
 */

export type FieldKind = 'text' | 'url' | 'email' | 'tel' | 'textarea' | 'select' | 'check';

export interface FieldDef {
  key: string;
  label: string;
  kind: FieldKind;
  placeholder?: string;
  /** Initial value for text-like fields. */
  initial?: string;
  /** Options for `select` fields: [value, label]. */
  options?: [string, string][];
  /** Render side-by-side with the next half-width field. */
  half?: boolean;
}

export type FieldValue = string | boolean;
export type FieldValues = Record<string, FieldValue>;

export interface ContentType {
  label: string;
  icon: string; // inner SVG markup for a 24×24 stroke icon
  fields: FieldDef[];
  /** Returns the QR payload, or '' when there isn't enough input yet. */
  build: (values: FieldValues) => string;
}

const str = (v: FieldValue | undefined): string => (typeof v === 'string' ? v : '');

/** Escape special characters in Wi-Fi QR fields (ZXing / Android convention). */
export const escapeWifi = (s: string): string => s.replace(/([\\;,:"])/g, '\\$1');

/** Escape a vCard 3.0 text value. */
export const escapeVCard = (s: string): string =>
  s.replace(/([\\;,])/g, '\\$1').replace(/\r?\n/g, '\\n');

const digitsOnly = (s: string): string => s.replace(/[^\d+]/g, '');

export const CONTENT_TYPES = {
  link: {
    label: 'Link',
    icon: '<path d="M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1"/>',
    fields: [{ key: 'url', label: 'Web address', kind: 'url', placeholder: 'quirk.example/hello', initial: 'https://example.com' }],
    build: (f) => {
      const u = str(f.url).trim();
      if (!u) return '';
      return /^[a-z][a-z0-9+.-]*:/i.test(u) ? u : 'https://' + u;
    },
  },
  text: {
    label: 'Text',
    icon: '<path d="M5 6h14M5 12h14M5 18h9"/>',
    fields: [{ key: 'text', label: 'Your message', kind: 'textarea', placeholder: 'Anything you like — a note, a code, a poem of your own…' }],
    build: (f) => str(f.text),
  },
  wifi: {
    label: 'Wi-Fi',
    icon: '<path d="M2 9a15 15 0 0 1 20 0M5 13a10 10 0 0 1 14 0M8.5 16.5a5 5 0 0 1 7 0"/><circle cx="12" cy="20" r="1"/>',
    fields: [
      { key: 'ssid', label: 'Network name', kind: 'text', placeholder: 'MyHomeWiFi' },
      { key: 'pass', label: 'Password', kind: 'text', placeholder: '••••••••' },
      { key: 'enc', label: 'Security', kind: 'select', options: [['WPA', 'WPA / WPA2 / WPA3'], ['WEP', 'WEP'], ['nopass', 'None (open)']] },
      { key: 'hidden', label: 'Hidden network', kind: 'check' },
    ],
    build: (f) => {
      const ssid = str(f.ssid);
      if (!ssid.trim()) return '';
      const enc = str(f.enc) || 'WPA';
      let s = `WIFI:T:${enc};S:${escapeWifi(ssid)};`;
      if (enc !== 'nopass') s += `P:${escapeWifi(str(f.pass))};`;
      if (f.hidden === true) s += 'H:true;';
      return s + ';';
    },
  },
  email: {
    label: 'Email',
    icon: '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 7l9 6 9-6"/>',
    fields: [
      { key: 'to', label: 'Send to', kind: 'email', placeholder: 'hello@example.com' },
      { key: 'sub', label: 'Subject', kind: 'text', placeholder: 'Hi there' },
      { key: 'body', label: 'Message', kind: 'textarea', placeholder: 'Optional' },
    ],
    build: (f) => {
      const to = str(f.to).trim();
      if (!to) return '';
      const q: string[] = [];
      if (str(f.sub)) q.push('subject=' + encodeURIComponent(str(f.sub)));
      if (str(f.body)) q.push('body=' + encodeURIComponent(str(f.body)));
      return 'mailto:' + to + (q.length ? '?' + q.join('&') : '');
    },
  },
  phone: {
    label: 'Call',
    icon: '<path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2"/>',
    fields: [{ key: 'tel', label: 'Phone number', kind: 'tel', placeholder: '+61 400 000 000' }],
    build: (f) => {
      const n = digitsOnly(str(f.tel));
      return n ? 'tel:' + n : '';
    },
  },
  sms: {
    label: 'SMS',
    icon: '<path d="M4 5h16v11H9l-5 4z"/>',
    fields: [
      { key: 'tel', label: 'Phone number', kind: 'tel', placeholder: '+61 400 000 000' },
      { key: 'msg', label: 'Message', kind: 'textarea', placeholder: 'Optional pre-filled text' },
    ],
    build: (f) => {
      const n = digitsOnly(str(f.tel));
      return n ? `SMSTO:${n}:${str(f.msg)}` : '';
    },
  },
  contact: {
    label: 'Contact',
    icon: '<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',
    fields: [
      { key: 'first', label: 'First name', kind: 'text', placeholder: 'Ada', half: true },
      { key: 'last', label: 'Last name', kind: 'text', placeholder: 'Lovelace', half: true },
      { key: 'org', label: 'Company', kind: 'text', placeholder: 'Optional', half: true },
      { key: 'title', label: 'Job title', kind: 'text', placeholder: 'Optional', half: true },
      { key: 'tel', label: 'Phone', kind: 'tel', placeholder: '+61 400 000 000', half: true },
      { key: 'email', label: 'Email', kind: 'email', placeholder: 'ada@example.com', half: true },
      { key: 'url', label: 'Website', kind: 'url', placeholder: 'Optional' },
    ],
    build: (f) => {
      const [first, last, org, title, tel, email, url] = ['first', 'last', 'org', 'title', 'tel', 'email', 'url'].map((k) =>
        str(f[k]).trim(),
      );
      if (!(first || last || tel || email)) return '';
      const lines = [
        'BEGIN:VCARD',
        'VERSION:3.0',
        `N:${escapeVCard(last)};${escapeVCard(first)};;;`,
        `FN:${escapeVCard(`${first} ${last}`.trim())}`,
      ];
      if (org) lines.push('ORG:' + escapeVCard(org));
      if (title) lines.push('TITLE:' + escapeVCard(title));
      if (tel) lines.push('TEL;TYPE=CELL:' + tel);
      if (email) lines.push('EMAIL:' + email);
      if (url) lines.push('URL:' + url);
      lines.push('END:VCARD');
      return lines.join('\n');
    },
  },
} satisfies Record<string, ContentType>;

export type ContentTypeId = keyof typeof CONTENT_TYPES;

export const isContentTypeId = (v: unknown): v is ContentTypeId =>
  typeof v === 'string' && Object.hasOwn(CONTENT_TYPES, v);

/** Default (initial) field values for every content type. */
export function defaultValues(): Record<ContentTypeId, FieldValues> {
  const out = {} as Record<ContentTypeId, FieldValues>;
  for (const [id, def] of Object.entries(CONTENT_TYPES) as [ContentTypeId, ContentType][]) {
    out[id] = {};
    for (const f of def.fields) {
      out[id][f.key] = f.kind === 'check' ? false : f.kind === 'select' ? f.options![0][0] : (f.initial ?? '');
    }
  }
  return out;
}

export const buildPayload = (type: ContentTypeId, values: FieldValues): string =>
  (CONTENT_TYPES[type] as ContentType).build(values) || '';
