import { isHexColor } from './color';
import { defaultValues, isContentTypeId, type ContentTypeId, type FieldValues } from './content-types';
import { DOT_SHAPES, EYE_SHAPES, type DotShape, type EyeShape } from './geometry';
import type { ErrorCorrection } from './qr';

export const EXPORT_SIZES = [512, 1024, 2048] as const;
export type ExportSize = (typeof EXPORT_SIZES)[number];

export interface AppState {
  type: ContentTypeId;
  values: Record<ContentTypeId, FieldValues>;
  fg: string;
  eye: string;
  bg: string;
  transparent: boolean;
  dot: DotShape;
  eyeShape: EyeShape;
  ec: ErrorCorrection;
  margin: number;
  size: ExportSize;
  preset: string | null;
}

export function initialState(): AppState {
  return {
    type: 'link',
    values: defaultValues(),
    fg: '#1B1A17',
    eye: '#FF5A36',
    bg: '#FFFDF8',
    transparent: false,
    dot: 'soft',
    eyeShape: 'rounded',
    ec: 'M',
    margin: 4,
    size: 1024,
    preset: 'quirk',
  };
}

const STORAGE_KEY = 'quirk-qr-v1';

/** Merge a saved (untrusted) blob into `base`, keeping only well-formed fields. */
export function mergeSaved(base: AppState, saved: unknown): AppState {
  if (!saved || typeof saved !== 'object') return base;
  const s = saved as Record<string, unknown>;
  const out: AppState = { ...base, values: structuredClone(base.values) };

  if (isContentTypeId(s.type)) out.type = s.type;
  if (s.values && typeof s.values === 'object') {
    for (const [t, vals] of Object.entries(s.values as Record<string, unknown>)) {
      if (!isContentTypeId(t) || !vals || typeof vals !== 'object') continue;
      for (const [k, v] of Object.entries(vals as Record<string, unknown>)) {
        if (k in out.values[t] && typeof v === typeof out.values[t][k]) out.values[t][k] = v as string | boolean;
      }
    }
  }
  if (isHexColor(s.fg)) out.fg = s.fg;
  if (isHexColor(s.eye)) out.eye = s.eye;
  if (isHexColor(s.bg)) out.bg = s.bg;
  if (typeof s.transparent === 'boolean') out.transparent = s.transparent;
  if (DOT_SHAPES.some(([v]) => v === s.dot)) out.dot = s.dot as DotShape;
  if (EYE_SHAPES.some(([v]) => v === s.eyeShape)) out.eyeShape = s.eyeShape as EyeShape;
  if (s.ec === 'L' || s.ec === 'M' || s.ec === 'Q' || s.ec === 'H') out.ec = s.ec;
  if (Number.isInteger(s.margin) && (s.margin as number) >= 0 && (s.margin as number) <= 8) out.margin = s.margin as number;
  if (EXPORT_SIZES.includes(s.size as ExportSize)) out.size = s.size as ExportSize;
  if (typeof s.preset === 'string' || s.preset === null) out.preset = s.preset;
  return out;
}

export function loadState(): AppState {
  const base = initialState();
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? mergeSaved(base, JSON.parse(raw)) : base;
  } catch {
    return base;
  }
}

export function saveState(state: AppState): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    /* storage unavailable (private mode, quota) — preferences just won't persist */
  }
}
